export function getGJMLAProfile(acNo: number): MLAProfile | undefined {
  return GJ_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getGJMLAsByParty(party: string): MLAProfile[] {
  return GJ_MLA_PROFILES.filter(p => p.party === party);
}

export function getGJFemaleMLAs(): MLAProfile[] {
  return GJ_MLA_PROFILES.filter(p => p.gender === 'F');
}
